import com.google.gson.Gson;
import com.google.gson.JsonParser;
import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch120Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("swsh9_en_133","swsh9a_en_025");
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static void select(ServerMatch m,UUID p,List<CardInstance> cards){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),cards.stream().map(CardInstance::instanceId).toList());}
    static ServerMatch game(String id){return game(id,false);}
    static ServerMatch game(String id,boolean listener){
        var kinds=List.of("basic","basic","basic","basic","trainer","copy","grass","water","fire","special","stadium");var defs=new ArrayList<CardDefinition>();
        for(String key:new LinkedHashSet<>(kinds)){boolean energy=Set.of("grass","water","fire","special").contains(key);defs.add(new CardDefinition(key,key,key.equals("basic")?CardCategory.POKEMON:energy?CardCategory.ENERGY:CardCategory.TRAINER,key.equals("stadium")?TrainerCategory.STADIUM:Set.of("trainer","copy").contains(key)?TrainerCategory.SUPPORTER:TrainerCategory.NONE,"H",Set.of("international"),key.equals("basic"),energy&&!key.equals("special"),60,Map.of(),EffectSupport.SUPPORTED,null));}
        var watcher=BundledCombatData.ability(JsonParser.parseString("{\"id\":\"deck-energy-watch\",\"nameZh\":\"Deck Energy watch\",\"kind\":\"TRIGGERED\",\"effectSupport\":\"SUPPORTED\",\"eventPolicy\":{\"trigger\":\"ON_ENERGY_ATTACHED\",\"target\":\"SELF\",\"source\":\"DECK\",\"cause\":\"EFFECT\",\"optional\":false,\"usage\":\"NONE\"},\"effects\":[{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":1}]}").getAsJsonObject(),EffectRegistry.standard());
        var pokemon=new PokemonProfile(1000,0,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(300,false)),listener?List.of(watcher):List.of(),EnergyType.GRASS);
        var combat=new CombatCatalog(Map.of("basic",pokemon),Map.of("grass",EnergyType.GRASS,"water",EnergyType.WATER,"fire",EnergyType.FIRE),Map.of("trainer",NonPokemonBatch2Test.DATA.trainer(id).orElseThrow(),"copy",NonPokemonBatch2Test.DATA.trainer("sm9_en_154").orElseThrow(),"stadium",NonPokemonBatch2Test.DATA.trainer("bw9_en_100").orElseThrow()),Map.of("special",EnergyProfile.fixed(EnergyType.WATER,2)));
        for(int seed=0;seed<150;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,kinds.get(i%kinds.size())));decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(x->x.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,22);m.drawCardsByEffect(A,B,22);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().anyMatch(p->List.of("trainer","copy","grass","water","fire","special","stadium").stream().anyMatch(key->m.privateView(p).hand().stream().noneMatch(x->x.definitionId().equals(key)))))continue;return m;}throw new AssertionError("No Cafe Master fixture");
    }
    static void fill(ServerMatch m,UUID p,int count){while(m.benchPokemonView(p).size()<count)m.playBasicPokemonToBench(p,hand(m,p,"basic").instanceId());}
    static List<CardInstance> hosts(ServerMatch m,UUID p,int count){return m.benchPokemonView(p).stream().limit(count).map(v->EventTargetBindingTest.field(m).topCard(p,v.pokemonId())).toList();}
    static List<CardInstance> prepareEnergy(ServerMatch m,UUID p){var energies=new ArrayList<CardInstance>();for(String id:List.of("grass","water","fire")){var card=hand(m,p,id);PairedTrainerPlayTest.zone(m,p,"hand").remove(card);PairedTrainerPlayTest.zone(m,p,"deck").add(card);energies.add(card);}return energies;}
    static ServerMatch aiGame(String id){var m=game(id);fill(m,A,3);prepareEnergy(m,A);return m;}
    static void assign(ServerMatch m,UUID p,List<CardInstance> energies,List<CardInstance> hosts){var q=m.effectAttachmentPrompt(p);for(int i=0;i<energies.size();i++)m.assignEffectEnergyDistribution(p,q.resolutionId(),q.step(),energies.get(i).instanceId(),PokemonIdentityTestSupport.logical(m,p,hosts.get(i).instanceId()));m.confirmEffectEnergyDistribution(p,q.resolutionId(),q.step());}
    public static void main(String[] args){attachments();noEffect();authority();oneType();locksAndEvents();copy();ai();schema();System.out.println("NonPokemonBatch120Test passed: both Cafe Master prints/players, 0-3 hosts fixed before deck visibility, distinct basic Energy and at most one per chosen Bench, simultaneous commit, no hand quota, no-match/partial decks, public host and private deck authority, stale/replay/foreign requests, copied Supporter turn ending, attachment triggers before turn end and four AI difficulties");}
    static void attachments(){for(String id:IDS)for(UUID p:List.of(A,B))for(int count=0;count<=3;count++){
        var m=game(id);if(p.equals(B))m.endTurn(A);fill(m,p,5);var targets=hosts(m,p,count);var energies=prepareEnergy(m,p);var card=hand(m,p,"trainer");int turn=m.turnNumber();var opponent=m.privateView(other(p));m.playTrainer(p,card.instanceId(),null);var q=m.effectCardPrompt(p);check(q.minimum()==0&&q.maximum()==3&&q.candidates().size()==5&&q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).basicPokemon()),"Host selection missing or exposed Energy before selecting Bench");select(m,p,targets);if(count==0){check(m.currentPlayer().equals(other(p))&&m.turnNumber()==turn+1,"Declining all hosts did not end turn");continue;}q=m.effectCardPrompt(p);check(q.maximum()==count&&q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).basicEnergy()),"Deck search allowed special energy or too many");check(m.currentPlayer().equals(p)&&m.turnNumber()==turn,"Ended turn before search");select(m,p,energies.subList(0,count));var distribution=m.effectAttachmentPrompt(p);check(distribution.targets().size()==count&&!distribution.targets().contains(active(m,p)),"Attachment allowed unchosen Bench/Active");for(var t:targets)check(EventTargetBindingTest.field(m).attachedEnergy(p,PokemonIdentityTestSupport.logical(m,p,t.instanceId())).isEmpty(),"Attached before whole distribution confirmed");assign(m,p,energies.subList(0,count),targets);check(m.currentPlayer().equals(other(p))&&m.turnNumber()==turn+1&&m.privateView(p).discard().contains(card)&&!m.energyAttached(p),"Cafe Master disposal, manual quota or turn ending wrong");for(int i=0;i<count;i++)check(EventTargetBindingTest.field(m).attachedEnergy(p,PokemonIdentityTestSupport.logical(m,p,targets.get(i).instanceId())).equals(List.of(energies.get(i))),"Wrong host or physical energy");check(m.privateView(other(p)).hand().size()==opponent.hand().size()+1,"Cafe Master altered opponent before natural next-turn draw");
    }}
    static void noEffect(){for(String id:IDS)for(String mode:List.of("empty-bench","empty-deck","no-basic","decline-energy")){
        var m=game(id);if(mode.equals("empty-bench"))for(var v:List.copyOf(m.benchPokemonView(A)))m.movePokemonByEffect(A,A,v.pokemonId(),LeavePlayDestination.HAND);if(mode.equals("empty-deck")){var deck=PairedTrainerPlayTest.zone(m,A,"deck");PairedTrainerPlayTest.zone(m,A,"discard").addAll(deck);deck.clear();}if(mode.equals("no-basic")){var deck=PairedTrainerPlayTest.zone(m,A,"deck");var basic=deck.stream().filter(c->m.cardDefinition(c.definitionId()).basicEnergy()).toList();deck.removeAll(basic);PairedTrainerPlayTest.zone(m,A,"discard").addAll(basic);}var card=hand(m,A,"trainer");if(mode.startsWith("empty")){check(!m.canPlayTrainer(A,card.instanceId(),null),"Cafe Master accepted empty public prerequisites");reject(()->m.playTrainer(A,card.instanceId(),null));continue;}m.playTrainer(A,card.instanceId(),null);select(m,A,hosts(m,A,1));if(m.hasPendingCardSelection())select(m,A,List.of());NonPokemonBatch103Test.settle(m);check(m.currentPlayer().equals(B)&&m.benchPokemonView(A).getFirst().attachedEnergyIds().isEmpty(),"No found/declined Energy did not complete end turn");
    }}
    static void authority(){var m=game(IDS.getFirst());fill(m,A,5);var energies=prepareEnergy(m,A);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);var first=m.effectCardPrompt(A);var deck=List.copyOf(m.privateView(A).deck());var session=MatchSession.multiplayer(m,A,B);String opponent=new Gson().toJson(session.view(B,B));for(var card:deck)check(!opponent.contains(card.instanceId().toString()),"Public host choice exposed private deck");reject(()->m.submitEffectCards(B,first.resolutionId(),first.step(),List.of()));reject(()->select(m,A,hosts(m,A,4)));reject(()->select(m,A,List.of(EventTargetBindingTest.field(m).topCard(A,active(m,A)))));reject(()->select(m,A,List.of(energies.getFirst())));var targets=hosts(m,A,3);select(m,A,targets);reject(()->m.submitEffectCards(A,first.resolutionId(),first.step(),List.of()));var search=m.effectCardPrompt(A);var same=search.candidates().stream().filter(c->c.definitionId().equals("grass")).limit(2).toList();if(same.size()==2)reject(()->select(m,A,same));select(m,A,energies);var q=m.effectAttachmentPrompt(A);UUID host=PokemonIdentityTestSupport.logical(m,A,targets.getFirst().instanceId());reject(()->m.assignEffectEnergyDistribution(B,q.resolutionId(),q.step(),energies.getFirst().instanceId(),host));reject(()->m.assignEffectEnergyDistribution(A,q.resolutionId(),q.step(),energies.getFirst().instanceId(),active(m,A)));m.assignEffectEnergyDistribution(A,q.resolutionId(),q.step(),energies.getFirst().instanceId(),host);m.assignEffectEnergyDistribution(A,q.resolutionId(),q.step(),energies.get(1).instanceId(),host);reject(()->m.confirmEffectEnergyDistribution(A,q.resolutionId(),q.step()));check(m.privateView(A).deck().containsAll(energies),"Invalid distribution moved Energy");assign(m,A,energies,targets);reject(()->m.confirmEffectEnergyDistribution(A,q.resolutionId(),q.step()));}
    static void oneType(){var m=game(IDS.getFirst());fill(m,A,3);prepareEnergy(m,A);var deck=PairedTrainerPlayTest.zone(m,A,"deck");var removed=deck.stream().filter(c->m.cardDefinition(c.definitionId()).basicEnergy()&&!c.definitionId().equals("grass")).toList();deck.removeAll(removed);PairedTrainerPlayTest.zone(m,A,"discard").addAll(removed);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);var targets=hosts(m,A,3);select(m,A,targets);var one=m.effectCardPrompt(A).candidates().getFirst();select(m,A,List.of(one));assign(m,A,List.of(one),targets);check(m.benchPokemonView(A).stream().mapToInt(v->v.attachedEnergyIds().size()).sum()==1&&m.currentPlayer().equals(B),"Only one available basic type did not attach exactly one");}
    static void locksAndEvents(){var m=game(IDS.getFirst(),true);fill(m,A,3);m.playTrainer(A,hand(m,A,"stadium").instanceId(),null);var targets=hosts(m,A,3);for(var target:targets)EventTargetBindingTest.field(m).preventHandEnergy(A,A,PokemonIdentityTestSupport.logical(m,A,target.instanceId()));var energies=prepareEnergy(m,A);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);select(m,A,targets);select(m,A,energies);int hand=m.privateView(A).hand().size();assign(m,A,energies,targets);NonPokemonBatch103Test.settle(m);check(m.privateView(A).hand().size()==hand+3&&m.benchPokemonView(A).stream().allMatch(v->v.damage()==0)&&m.currentPlayer().equals(B),"Deck attachment failed triggers, used hand lock/Frozen City or ended before reactions");}
    static void copy(){for(UUID p:List.of(A,B)){var m=game(IDS.getFirst());if(p.equals(B))m.endTurn(A);var copied=hand(m,other(p),"trainer");int turn=m.turnNumber();m.playTrainer(p,hand(m,p,"copy").instanceId(),null);var reveal=m.effectCardReveal();if(reveal!=null)m.acknowledgeEffectReveal(reveal.confirmingPlayer(),reveal.id());select(m,p,List.of(copied));select(m,p,List.of());NonPokemonBatch103Test.settle(m);check(m.currentPlayer().equals(other(p))&&m.turnNumber()==turn+1&&m.privateView(other(p)).hand().contains(copied),"Copied Cafe Master did not end turn or consumed opponent's card");}}
    static void ai(){for(String id:IDS)for(var difficulty:AiDifficulty.values()){var m=aiGame(id);var s=MatchSession.multiplayer(m,A,B);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);AiCardOperationTest.settle(s,difficulty);AiCardOperationTest.finish(s,difficulty);check(m.phase()==MatchPhase.FINISHED,"Cafe Master AI stalled "+id+" "+difficulty);}}
    static void schema(){var registry=EffectRegistry.standard();reject(()->registry.parse(JsonParser.parseString("{\"type\":\"prepare_distinct_bench_energy\",\"target\":\"OWN_ACTIVE\"}").getAsJsonObject()));reject(()->DistinctBenchEnergy.attachment(4));var valid=DistinctBenchEnergy.attachment(3);var args=new HashMap<>(valid.arguments());args.put("distinct_energy_types","false");reject(()->AttachEnergyEffect.from(new EffectDefinition(valid.type(),valid.target(),args,List.of(),List.of())));}
}
